let registration = UICollectionView.CellRegistration<UICollectionViewListCell, Post.ID> { cell, _, id in
    let post = store.post(id)
    var content = cell.defaultContentConfiguration()
    content.text = post.title
    content.secondaryText = post.author
    cell.contentConfiguration = content
}
let dataSource = UICollectionViewDiffableDataSource<Section, Post.ID>(collectionView: collectionView) {
    cv, indexPath, id in cv.dequeueConfiguredReusableCell(using: registration, for: indexPath, item: id)
}

var snapshot = NSDiffableDataSourceSnapshot<Section, Post.ID>()
snapshot.appendSections([.main])
snapshot.appendItems(posts.map(\.id))
dataSource.apply(snapshot, animatingDifferences: true)

// Later: a post's like count changed
var s = dataSource.snapshot()
s.reconfigureItems([post.id])
dataSource.apply(s)
